         *
         * @param listeSommets la liste de sommets à visiter sans répétition ;
         *                     pré-requis : c'est une sous-liste de la liste retournée
         * @return une liste d'entiers correspondant aux sommets du chemin.
         * Si le chemin n'existe pas, retourne une liste vide.
         */
        public List<Integer> parcoursSansRepetition(List<Integer> listeSommets) {
            List<Integer> chemin = new ArrayList<>();
            Set<Integer> sommetsVisites = new HashSet<>();
            for (int sommet : listeSommets) {
                if (!sommetsVisites.contains(sommet)) parcoursDFS(sommet, chemin, sommetsVisites);
            }
            boolean cheminComplet = true;
            for (int sommet : listeSommets) {
                if (!chemin.contains(sommet)) {
                    cheminComplet = false;
                    break;
                }
            }
            List<Integer> chiffreASuppr = new ArrayList<>();
            if (cheminComplet) {
                int n = 0;
                for (int sommet : chemin) {
                    if(n == listeSommets.size()) chiffreASuppr.add(sommet);
                    if (listeSommets.contains(sommet)) n++;
                }
                for(Integer i : chiffreASuppr) {
                    chemin.remove(i);
                }
                return chemin;
            } else return new ArrayList<>();
        }


        private void parcoursDFS(int sommet, List<Integer> chemin, Set<Integer> sommetsVisites) {
            chemin.add(sommet);
            sommetsVisites.add(sommet);

            Set<Integer> voisins = getVoisins(sommet);
            for (int voisin : voisins) {
                if (!sommetsVisites.contains(voisin)) parcoursDFS(voisin, chemin, sommetsVisites);
            }
        }

        private Route getRoute(int sommet1, int sommet2) {
            for(Route route : Plateau.makePlateauMonde().getRoutes()) {
                if(route.getVille1().getId() == sommet1 && route.getVille2().getId() == sommet2) {
                    return route;
                }
            }
            return null;
        }

        private List<Integer> dijkstra(int depart, int arrivee) {
            if (!mapAretes.containsKey(depart) || !mapAretes.containsKey(arrivee)) return new ArrayList<>();
            Map<Integer, Integer> distances = new HashMap<>();
            Map<Integer, Integer> predecesseurs = new HashMap<>();
            PriorityQueue<Integer> filePriorite = new PriorityQueue<>(Comparator.comparingInt(distances::get));
            for (Integer sommet : mapAretes.keySet()) {
                if (sommet == depart) distances.put(sommet, 0);
                else distances.put(sommet, Integer.MAX_VALUE);
                filePriorite.add(sommet);
            }
            while (!filePriorite.isEmpty()) {
                Integer sommetCourant = filePriorite.poll();
                if (sommetCourant == arrivee) break;
                Set<Integer> voisins = getVoisins(sommetCourant);
                for (Integer voisin : voisins) {
                    int poidsArete = Objects.requireNonNull(getRoute(sommetCourant, voisin)).getLongueur();
                    int distanceVoisin = distances.get(sommetCourant) + poidsArete;
                    if (distanceVoisin < distances.get(voisin)) {
                        distances.put(voisin, distanceVoisin);
                        predecesseurs.put(voisin, sommetCourant);
                        filePriorite.remove(voisin);
                        filePriorite.add(voisin);
                    }
                }
            }
            List<Integer> chemin = new ArrayList<>();
            Integer sommet = arrivee;
            while (sommet != null) {
                chemin.add(0, sommet);
                sommet = predecesseurs.get(sommet);
            }
            if (chemin.size() > 1 && chemin.get(0) == depart) return chemin;
            else return new ArrayList<>();
        }

        /**
         * Retourne un plus petit ensemble bloquant de routes entre deux villes. Cette fonction supposera que `this` est
