    | expression SUB expression {
        int result = atoi($1) - atoi($3);
        char buffer[20];  // Adjust the buffer size as needed
        sprintf(buffer, "%d", result);
        $$ = strdup(buffer);}
    | expression MUL expression {
        int result = atoi($1) * atoi($3);
        char buffer[20];  // Adjust the buffer size as needed
        sprintf(buffer, "%d", result);
        $$ = strdup(buffer);}
    | expression DIV expression {
        int result = atoi($1) / atoi($3);
        char buffer[20];  // Adjust the buffer size as needed
        sprintf(buffer, "%d", result);
        $$ = strdup(buffer);}
    | expression MOD expression {
        int result = atoi($1) % atoi($3);
        char buffer[20];  // Adjust the buffer size as needed
        sprintf(buffer, "%d", result);
        $$ = strdup(buffer);}
    | expression EQ expression {
        bool result = $1 == $3;
        char* str_result = result ? "true" : "false";
        $$ = strdup(str_result);}
    | expression LT expression {
        bool result = $1 < $3;
        char* str_result = result ? "true" : "false";
        $$ = strdup(str_result);}
    | expression GT expression {
        bool result = $1 > $3;
        char* str_result = result ? "true" : "false";
        $$ = strdup(str_result);}
    | expression LE expression {
        bool result = $1 <= $3;
        char* str_result = result ? "true" : "false";
        $$ = strdup(str_result);}
    | expression GE expression {
        bool result = $1 >= $3;
        char* str_result = result ? "true" : "false";
        $$ = strdup(str_result);}
    | expression NEQ expression {
        bool result = $1 != $3;
        char* str_result = result ? "true" : "false";
        $$ = strdup(str_result);}
    | expression AND expression {
        bool result = $1 && $3;
        char* str_result = result ? "true" : "false";
        $$ = strdup(str_result);}
    | expression OR expression {
        bool result = $1 || $3;
        char* str_result = result ? "true" : "false";
        $$ = strdup(str_result);}
    | NOT expression {
        int result = atoi($2);
        char buffer[20];  // Adjust the buffer size as needed
        sprintf(buffer, "%d", result);}
    | ADD expression {$$ = $2;}
    | SUB expression {
        int result = atoi($2);  result = -result;
        char buffer[20];  // Adjust the buffer size as needed
        sprintf(buffer, "%d", result);}
    | LPAREN expression RPAREN {$$ = $2;}
    | NUMBER {
        int result = $1;
        char buffer[20];  // Adjust the buffer size as needed
        sprintf(buffer, "%d", result);}
    | IDENTIFIER {printf("identifier: %s\n", $1);}
    | function_call {$$ = $1;}
    ;

function_call:
