function u = V_xunhuan(u, f, h, level)
    if level == 0
        return
    end
    % 预平滑
    u = smoothing(u, f, h);
    % 计算残差
    r_old = cancha(u, f, h);
    % 限制
    r_new = xianzhi(r_old);
    % 计算误差
    e = zeros(size(r_new));
    % 如果网格已经达到最粗，停止递归，否则继续递归
    if (length(r_new) - 1) / 2 == 2
        e = smoothing(e, r_new, 2 * h);
    else
        f_new = xianzhi(f);
        e = V_xunhuan(e, f_new, 2 * h, level - 1);
    end
    % 修正
    u = u + yantuo(e);
    % 后光滑
    u = smoothing(u, f, h);
end

function res = smoothing(phi, f, h)
    N = size(phi, 1) - 1;
    res = phi;
    for i = 2:N
        for j = 2:N
            res(i, j) = (phi(i+1, j) + res(i-1, j) + phi(i, j+1) + res(i, j-1) + h^2 * f(i, j))/4;
        end
    end
end

function res = cancha(phi, f, h)
    N = size(phi, 1) - 1;
    res = zeros(N+1, N+1);
    res(2:N, 2:N) = f(2:N, 2:N) - (phi(1:N-1, 2:N)-2*phi(2:N, 2:N)+phi(3:N+1, 2:N)+phi(2:N, 1:N-1)-2*phi(2:N, 2:N)+phi(2:N, 3:N+1))/h^2;
end

function r_xi = xianzhi(r_cu)
    N = (size(r_cu, 1) - 1) / 2;
    r_xi = zeros(N+1, N+1);
    for i = 2:N
        for j = 2:N
            r_xi(i, j) = 2/16 * (r_cu(2 * i, 2 * j-1) + r_cu(2 * i, 2 * j+1) + r_cu(2 * i-1, 2 * j) + r_cu(2 * i+1, 2 * j)) + 1/2 * r_cu(2 * i, 2 * j);
        end
    end
end

function e_xiwang = yantuo(e_cuwang)
    N = (size(e_cuwang, 1) - 1) * 2; % 计算细网格的大小
    e_xiwang = zeros(N + 1, N + 1); % 初始化细网格矩阵

    for i = 1:2:N + 1
        for j = 1:2:N + 1
            e_xiwang(i, j) = e_cuwang((i + 1) / 2, (j + 1) / 2);
        end
    end

    for i = 2:2:N
        for j = 2:2:N
            e_xiwang(i, j) = 1/4 * (e_cuwang(i / 2, j / 2) + e_cuwang((i+2)/ 2 , j / 2) + e_cuwang(i / 2, (j+2)/2) + e_cuwang((i+2) / 2 , (j+2)/2));
        end
    end

    for i = 1:2:N+1
        for j = 2:2:N
            e_xiwang(i, j) = 1/2 * (e_cuwang((i + 1) / 2, j / 2) + e_cuwang((i+ 1)/2, (j+2)/ 2));
        end
    end

    for i = 2:2:N
        for j = 1:2:N+1
            e_xiwang(i, j) = 1/2 * (e_cuwang(i / 2, (j + 1) / 2) + e_cuwang((i +2)/ 2 , (j + 1) / 2));
        end
    end
end

