function mergeComments(phoneNumbers) {
  const result = [];

  phoneNumbers.forEach((phoneNumber) => {
    const existingEntry = result.find((entry) => entry.number === phoneNumber.number);

    if (!existingEntry) {
      result.push({
        number: phoneNumber.number,
        url: phoneNumber.url,
        comments: [...phoneNumber.comments],
        callType: phoneNumber.callType,
      });
    } else {
      existingEntry.comments.push(...phoneNumber.comments);
      existingEntry.comments = Array.from(new Set(existingEntry.comments));
    }
  });

  return result;
}

