#include <omp.h>
int main()
{
    int i;
    double step;
    double x, pi;
    double sum = 0.0, start_time, end_time;
    int num_steps = 100000000;

    step = 1.0 / (double) num_steps;

    start_time = omp_get_wtime();
    #pragma omp parallel private(x) 
    {
        double local_sum = 0.0;
        #pragma omp for nowait
        for (i = 0; i < num_steps; i++)
        {
            x = (i + 0.5) * step;
            local_sum += 4.0 / (1.0 + x * x);
        }
        #pragma omp atomic
        sum += local_sum;
    }
    pi = step * sum;
    end_time = omp_get_wtime();

    printf("pi is approximately: %.16lf\n", pi);
    printf("time %.5lf seconds\n", end_time - start_time);
    printf("Speedup: %.2lf\n", (double)(num_steps)/(end_time - start_time)/1000000);

    return 0;
}
