function phi = V_Cycle(phi,f,h)
% Recursive V-Cycle Multigrid for solving the Poisson equation (\nabla^2 phi = f) on a uniform grid of spacing h

% Pre-Smoothing
phi = smoothing(phi,f,h);

% Compute Residual Errors
r = residual(phi,f,h);

% Restriction
rhs = restriction®;

eps = zeros(size(rhs));

% stop recursion at smallest grid size, otherwise continue recursion
if length(eps)-1 == 2
eps = smoothing(eps,rhs,2h);
else
eps = V_Cycle(eps,rhs,2h);
end

% Prolongation and Correction
phi = phi + prolongation(eps);

% Post-Smoothing
phi = smoothing(phi,f,h);
end

function res = smoothing(phi,f,h)
N = size(phi, 1) - 1;
res = zeros(N+1, N+1);
for i = 2:N
for j = 2:N
res(i, j) = (phi(i-1, j)+res(i-1, j)+phi(i+1, j)+res(i, j-1)-h^2f(i, j))/4;
end
end
end

function res = residual(phi,f,h)
N = size(phi, 1) - 1;
res = zeros(N+1, N+1);
res(2:N, 2:N) = f(2:N, 2:N)-(phi(1:N-1, 2:N)-2phi(2:N, 2:N)+phi(3:N+1, 2:N)+phi(2:N, 1:N-1)-2phi(2:N, 2:N)+phi(2:N, 3:N+1))/h^2;
end

function res = restriction®
N = (size(r, 1) - 1) / 2;
res = zeros(N+1, N+1);
for i = 2:N
for j = 2:N
res(i, j) = (r(2i-2, 2j-2)+2r(2i-1, 2j-2)+r(2i, 2j-2)+2r(2i-2, 2j-1)+4r(2i-1, 2j-1)+2r(2i, 2j-1)+r(2i-2, 2j)+2r(2i-1, 2j)+r(2i, 2*j))/16;
end
end
end

function res = prolongation(eps)
N = (size(eps, 1) - 1) * 2;
res = zeros(N+1, N+1);
for i = 2:2:N
for j = 2:2:N
res(i, j) = eps(i/2, j/2)/4;
end
end
for i = 1:2:N+1
for j = 1:2:N+1
res(i, j) = eps((i+1)/2, (j+1)/2);
end
end
for i = 1:2:N
for j = 2:2:N
res(i, j) = (eps((i+1)/2, j/2) + eps((i+1)/2, j/2+1))/4;
end
end
for i = 2:2:N
for j = 1:2:N
res(i, j) = (eps(i/2, (j+1)/2) + eps(i/2+1, (j+1)/2))/4;
end
end
end

