func RandStringRunes(n int, runes_optional ...[]rune) string {
	var runes = letterRunes
	if len(runes_optional) != 0 {
		runes = runes_optional[0]
	}
	b := make([]rune, n)
	for i := range b {
		b[i] = letterRunes[rand.Intn(len(runes))]
	}
	return string(b)
}

