        while (fscanf(file, “%s”, word) != EOF) {
            for (i = 0; i < strlen(word); i++) {
                word[i] = tolower(word[i]);
            }

            WordInfo entry = find_word(word, table);
            if (entry->word == NULL) {
                entry->word = (char)malloc(sizeof(char) * (strlen(word) + 1));
                strcpy(entry->word, word);
            }
            entry->count++;
        }
    }

    fclose(file);
}

int cmpfunc(const void *a, const void *b) {
    WordInfo w1 = (WordInfo)a;
    WordInfo w2 = (WordInfo)b;

    if (w1->count < w2->count) return 1;
    else if (w1->count > w2->count) return -1;
    else return 0;
}

void print_table(WordInfo *table) {
    int i;
    WordInfo sorted_table[NUM_BUCKETS];
    memcpy(sorted_table, table, sizeof(WordInfo) * NUM_BUCKETS);

    qsort(sorted_table, NUM_BUCKETS, sizeof(WordInfo), cmpfunc);

    for (i = 0; i < NUM_BUCKETS; i++) {
        if (sorted_table[i].word != NULL) {
            printf(“%s: %d\n”, sorted_table[i].word, sorted_table[i].count);
        }
    }
}

void free_table(WordInfo *table) {
    int i;
    for (i = 0; i < NUM_BUCKETS; i++) {
        if (table[i].word != NULL) {
            free(table[i].word);
        }
    }
}

int main() {
    WordInfo table[NUM_BUCKETS] = {{NULL, 0}};
    int num_threads = 4;

    count_words(“example.txt”, table, num_threads);
    print_table(table);
    free_table(table);
    return 0;
